/* aesthetic shell v2.19.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-w-medium: 550;
  --ae-w-black: 800;
  --ae-measure: 38rem;
  --ae-space-5: 1.5em;
  --ae-space-6: 2em;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
}

.ae-screen {
height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.ae-bar {
flex: none;
  width: min(var(--ae-measure), 100% - 5rem);
  margin-inline: auto;
  padding: 1.4em 0;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.4em 1.5em;
}

.ae-stage {
flex: 1;
  min-height: 0;
  width: min(var(--ae-measure), 100% - 5rem);
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.ae-stage > * {
margin-block: auto;
  padding-block: var(--ae-space-5);
}

.ae-view {
animation: ae-enter var(--ae-soft) var(--ae-ease) both;
}

.ae-nav {
position: relative;
  display: flex;
  gap: var(--ae-space-6);
}

.ae-nav a,
.ae-nav button {
background: transparent;
  border: 0;
  padding: 0 0 0.6em;
  margin-block: 0;
  cursor: pointer;
  color: var(--ae-ink-muted);
  font-weight: var(--ae-w-medium);
  text-decoration: none;
  transition: color var(--ae-quick) var(--ae-ease);
}

.ae-nav a:hover,
.ae-nav button:hover {
color: var(--ae-ink);
}

.ae-nav [aria-current],
.ae-nav .is-active {
color: var(--ae-ink);
}

.ae-mode {
position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.2em;
  height: 2.2em;
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  color: var(--ae-ink-muted);
  transition: color var(--ae-quick) var(--ae-ease);
}

.ae-mode::before {
content: '\200b';
}

.ae-mode:hover {
color: var(--ae-ink);
}

.ae-name {
font-weight: var(--ae-w-black);
  letter-spacing: 0.38em;
}

a.ae-name {
text-decoration: none;
}

@media (max-width: 40rem) {
  .ae-bar,
  .ae-stage {
  width: calc(100% - 2.4rem);
  }
}

@keyframes ae-enter {
from {
    opacity: 0;
    transform: translateY(6px);
  }
}

/* the mode: light and dark, defaulting to the system, with a toggle.

   The boot — read the persisted choice before first paint so the page
   never flashes the wrong mode — must be inlined in <head>:

   <script>
     try {
       var m = localStorage.getItem('ae-mode');
       if (m === 'dark' || m === 'light') {
         document.documentElement.classList.add(m);
         document.documentElement.style.colorScheme = m;
       }
     } catch (e) {}
   </script>

   The toggle below pins the opposite of the effective scheme. Pinning
   color-scheme keeps UA widgets (scrollbars, form controls) on the
   pinned side even when the OS disagrees. The change itself is quick
   and interruptible: a new click cuts any in-flight transition and
   applies the newest mode immediately. Unsupported view transitions
   get the same quick color ease; reduced motion is instant.
   next-themes consumers: keep attribute="class" and skip this file —
   the classes match. */
(() => {
  const root = document.documentElement;
  let activeTransition = null;
  let easingTimer = 0;
  let runId = 0;
  let targetDark = null;

  const isDark = () =>
    root.classList.contains('dark')
      ? true
      : root.classList.contains('light')
        ? false
        : matchMedia('(prefers-color-scheme: dark)').matches;

  const reducedMode = matchMedia('(prefers-reduced-motion: reduce)');

  const clearAnimation = () => {
    if (activeTransition && activeTransition.skipTransition) {
      activeTransition.skipTransition();
    }
    activeTransition = null;
    if (easingTimer) {
      clearTimeout(easingTimer);
      easingTimer = 0;
    }
    root.classList.remove('ae-vt-mode', 'ae-mode-easing');
  };

  const applyMode = (dark) => {
    root.classList.toggle('dark', dark);
    root.classList.toggle('light', !dark);
    root.style.colorScheme = dark ? 'dark' : 'light';
    try {
      localStorage.setItem('ae-mode', dark ? 'dark' : 'light');
    } catch (e) {}
  };

  document.querySelectorAll('.ae-mode').forEach((btn) => {
    btn.addEventListener('click', () => {
      const nextDark = !(targetDark ?? isDark());
      const id = ++runId;
      targetDark = nextDark;
      const flip = () => {
        if (id !== runId) return;
        applyMode(nextDark);
      };
      clearAnimation();
      if (reducedMode.matches) {
        flip();
      } else if (document.startViewTransition) {
        root.classList.add('ae-vt-mode');
        activeTransition = document.startViewTransition(flip);
        easingTimer = setTimeout(() => {
          if (id !== runId) return;
          root.classList.remove('ae-vt-mode');
          easingTimer = 0;
        }, 180);
        activeTransition.finished.finally(() => {
          if (id !== runId) return;
          root.classList.remove('ae-vt-mode');
          activeTransition = null;
          if (easingTimer) {
            clearTimeout(easingTimer);
            easingTimer = 0;
          }
        });
      } else {
        root.classList.add('ae-mode-easing');
        flip();
        easingTimer = setTimeout(() => {
          if (id !== runId) return;
          root.classList.remove('ae-mode-easing');
          easingTimer = 0;
        }, 180);
      }
    });
  });
})();

/* the nav indicator: position the sliding ink underline under the
   active item on activation, resize, and font load (metrics shift
   when Geist arrives). Exposes window.aePlaceInds for page scripts
   that swap views and need the indicator re-placed after a display
   change. Works for .ae-nav and .ae-tabs alike. */
(() => {
  if (window.aePlaceInds) return;
  const placeInd = (nav) => {
    const active = nav.querySelector(
      '[aria-current], [aria-selected="true"], .is-active',
    );
    const ind = nav.querySelector('.ae-nav-ind');
    if (!active || !ind || !nav.offsetWidth) return;
    ind.style.left = active.offsetLeft + 'px';
    ind.style.width = active.offsetWidth + 'px';
  };
  const placeAllInds = () =>
    document.querySelectorAll('.ae-nav, .ae-tabs').forEach(placeInd);

  document.querySelectorAll('.ae-nav, .ae-tabs').forEach((nav) => {
    nav.querySelectorAll('a, button').forEach((item) => {
      item.addEventListener('click', () => {
        nav
          .querySelectorAll('a, button')
          .forEach((b) => b.classList.remove('is-active'));
        item.classList.add('is-active');
        placeInd(nav);
      });
    });
  });
  addEventListener('resize', placeAllInds);
  if (document.fonts) document.fonts.ready.then(placeAllInds);
  placeAllInds();

  window.aePlaceInds = placeAllInds;
})();

/* view swap by hash: give each view data-route="name" and link to it
   with href="#name". The matching view mounts (.is-on) and replays
   its entrance; everything else unmounts. Falls back to
   data-route="index" when the hash names nothing. */
(() => {
  const views = document.querySelectorAll('[data-route]');
  if (!views.length) return;
  const show = () => {
    const route = location.hash.slice(1) || 'index';
    let hit = false;
    views.forEach((v) => {
      const on = v.dataset.route === route;
      v.classList.toggle('is-on', on);
      hit = hit || on;
    });
    if (!hit)
      views.forEach((v) =>
        v.classList.toggle('is-on', v.dataset.route === 'index'),
      );
    if (window.aePlaceInds) requestAnimationFrame(window.aePlaceInds);
  };
  addEventListener('hashchange', show);
  show();
})();
